-- Remove rooms from earlier generated imports before inserting the audited 189-room set.
DELETE FROM rooms
WHERE facility_id IN (
  SELECT id FROM facilities
  WHERE code = ANY (ARRAY[
    'ABE', 'ADMIN', 'BIOTECH', 'CAF', 'CAS', 'CET', 'CFNR', 'CHEM', 'COMART', 'CSAT', 'CVM', 'DA', 'DABE', 'DAEEX', 'DALL', 'DAS', 'DBM', 'DBS', 'DBT', 'DCE', 'DCST', 'DDC', 'DECON', 'DFS', 'DFST', 'DGE', 'DHM', 'DLABS', 'DMATH', 'DME', 'DMET', 'DOE', 'DOH', 'DON', 'DOPAC', 'DPBG', 'DPHYS', 'DPM', 'DPSS', 'DSS', 'DSTAT', 'DTE', 'DTED', 'DTHM', 'DTM', 'DVM', 'ECON', 'FON', 'FT', 'GE', 'HIGHSC', 'HOMESCI', 'IHK', 'ISRDS', 'ITEEM', 'MATH', 'MATHNS', 'ME', 'MECH', 'NURS', 'PHYS', 'STAT', 'VACADMIN'
  ]::text[])
);

