  'VM-B14',
  NULL,
  NULL,
  'Capacity: 50'
FROM facilities
WHERE code = 'DVM'
ON CONFLICT (facility_id, room_code) DO UPDATE SET
  name = EXCLUDED.name,
  floor = EXCLUDED.floor,
  description = EXCLUDED.description;

